-- Generated by dbt/sync_models.py from sql/mart/dim_customer.sql. Do not edit.
-- One row per customer_unique_id. A person seen in several states keeps the state of
-- the latest order (39 ids in raw data; KPI spec K13).
WITH c AS (
    SELECT c.customer_unique_id, c.state, o.purchase_ts
    FROM {{ ref('stg_customers') }} c
    LEFT JOIN {{ ref('stg_orders') }} o USING (customer_id)
),
latest AS (
    SELECT customer_unique_id, state
    FROM c
    QUALIFY row_number() OVER (
        PARTITION BY customer_unique_id ORDER BY purchase_ts DESC NULLS LAST, state) = 1
)
SELECT CAST(row_number() OVER (ORDER BY customer_unique_id) AS INTEGER) AS customer_key,
       customer_unique_id,
       state
FROM latest
ORDER BY customer_key
